function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  for var i := 0 to numbers.Length - 2 do
    for var j := i + 1 to numbers.Length - 1 do
      if Abs(numbers[i] - numbers[j]) < threshold then
      begin
        Result := True;
        exit;
      end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<string>;
  var resultList := new List<string>;
  var current := '';
  var ignoreSpaces := True;

  foreach var ch in parenString do
  begin
    if ch = ' ' then
      continue
    else if ch = '(' then
    begin
      if ignoreSpaces then
        current += ch
      else
        stack.Push(current);
        current := '';
    end
    else if ch = ')' then
    begin
      if ignoreSpaces then
        current += ch
      else
      begin
        stack.Push(current);
        current := '';
        if stack.Count > 0 then
          current += stack.Pop;
        resultList.Add(current);
        current := '';
      end;
    end;
  end;

  Result := resultList.ToArray;
end;


