function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  if n = 0 then
  begin
    Result := '';
    exit;
  end;

  var postfix := str;
  for var i := n - 1 downto 0 do
  begin
    if IsPalindrome(str.Substring(i)) then
    begin
      postfix := str.Substring(0, i);
      break;
    end;
  end;

  var prefix := str.Substring(0, n - postfix.Length);
  Result := str + ReverseString(prefix);
end;


