function ParseMusic(musicString: string): array of integer;
begin
  var notes := musicString.Split(' ');
  var beats := new List<integer>;
  var last := #0;

  foreach var note in notes do
  begin
    if note = 'o' then
      beats.Add(4)
    else if note = 'o|' then
      beats.Add(2)
    else if note = '.|' then
      beats.Add(1)

    if note <> last then
      beats.Add(4)
    last := note;
  end;

  Result := beats.ToArray;
end;


