function FindClosestElements(numbers: array of real): (real, real);
begin
  var sorted := numbers.ToArray;
  sorted.Sort;
  var minDiff := real.MaxValue;
  var closest := (0, 0);

  for var i := 0 to sorted.Length - 2 do
  begin
    var diff := sorted[i+1] - sorted[i];
    if diff < minDiff then
    begin
      minDiff := diff;
      closest := (sorted[i], sorted[i+1]);
    end;
  end;

  Result := closest;
end;


function RescaleToUnit(numbers: array of real): array of real;
begin
  if numbers.Length < 2 then
    raise new System.ArgumentException('Input array must contain at least two elements');
  var minVal := numbers.Min;
  var maxVal := numbers.Max;
  var scale := 1.0 / (maxVal - minVal);
  var offset := -minVal;
  for var i := 0 to numbers.Length - 1 do
    numbers[i] := (numbers[i] - offset) * scale;
  Result := numbers;
end;


