function TriplesSumToZero(l: array of integer): boolean;
begin
  var sorted := l.ToArray;
  sorted.Sort;
  for var i := 0 to sorted.Length - 3 do
  begin
    var left := i + 1;
    var right := sorted.Length - 1;
    while left < right do
    begin
      var currentSum := sorted[i] + sorted[left] + sorted[right];
      if currentSum = 0 then
      begin
        Result := True;
        exit;
      end
      else if currentSum < 0 then
        left += 1
      else
        right -= 1;
    end;
  end;
  Result := False;
end;


