function ChangeBase(x: integer; base: integer): string;
begin
  if (base < 2) or (base > 10) then
    raise new System.ArgumentException('Base must be between 2 and 10');
  var sb := new System.Text.StringBuilder;
  while x > 0 do
  begin
    sb.Insert(0, x mod base);
    x := x div base;
  end;
  Result := sb.ToString;
end;


