function CorrectBracketing(brackets: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var bracket in brackets do
    if bracket = '<' then
      stack.Push(bracket)
    else if bracket = '>' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  Result := stack.Count = 0;
end;


function Monotonic(l: array of integer): boolean;
begin
  if l.Length = 0 then
  begin
    Result := True;
    exit;
  end;

  var increasing := True;
  var decreasing := True;

  for var i := 1 to l.Length - 1 do
  begin
    if l[i] > l[i-1] then
      decreasing := False
    else if l[i] < l[i-1] then
      increasing := False;
  end;

  Result := increasing or decreasing;
end;


