function Pluck(arr: array of integer): array of integer;
begin
  var smallestEven := integer.MaxValue;
  var smallestIndex := -1;
  var smallestValue := -1;
  var index := 0;

  foreach var value in arr do
  begin
    if (value mod 2 = 0) and (value < smallestEven) then
    begin
      smallestEven := value;
      smallestIndex := index;
      smallestValue := value;
    end
    else if (value = smallestValue) and (index < smallestIndex) then
      smallestIndex := index;
    index += 1;
  end;

  if smallestValue <> -1 then
    Result := |smallestValue, smallestIndex|
  else
    Result := |0, -1|;
end;


function Search(lst: array of integer): integer;
