  foreach var i in lst do
    if count.ContainsKey(i) then
      count[i] += 1
    else
      count[i] := 1;
  var maxVal := -1;
  foreach var kv in count do
    if kv.Value >= kv.Key then
      if (kv.Key > maxVal) or ((kv.Key = maxVal) and (kv.Key > maxVal)) then
        maxVal := kv.Key;
  Result := maxVal;
end;


function StrangeSortList(lst: array of integer): array of integer;
