      if grid[i][j] = 1 then
        buckets[i, j] := 1;

  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
      if buckets[i, j] = 1 then
      begin
        var min := cols;
        var max := 0;

        for var k := 0 to cols - 1 do
          if buckets[i, k] = 1 then
          begin
            min := Min(min, k);
            max := Max(max, k);
          end;

        for var k := min to max do
          buckets[i, k] := 0;

        count += 1;
      end;

  Result := count;
end;


