function ProdSigns(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sign := 1;
  var prod := 1;
  var sum := 0;

  foreach var num in arr do
  begin
    if num = 0 then
    begin
      Result := 0;
      exit;
    end;

    if num < 0 then
      sign := -sign;

    prod := prod * sign;
    sum := sum + Abs(num);
  end;

  Result := prod * sum;
end;


function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := new List<(integer, integer)>;
  directions.Add((0, 1));
  directions.Add((1, 0));
  directions.Add((0, -1));
  directions.Add((-1, 0));

  var visited := new HashSet<(integer, integer)>;
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((0, 0, 0));
  var path := new List<integer>;

  while queue.Count > 0 do
  begin
    var (x, y, steps) := queue.Dequeue;
    if steps = k then
    begin
      path.Add(grid[x, y]);
      Result := path.ToArray;
      exit;
    end;

    foreach var (dx, dy) in directions do
    begin
      var nx := x + dx;
      var ny := y + dy;
      if (nx >= 0) and (nx < n) and (ny >= 0) and (ny < n) and not visited.Contains((nx, ny)) then
      begin
        visited.Add((nx, ny));
        queue.Enqueue((nx, ny, steps + 1));
      end;
    end;
  end;

  Result := new integer[0];
end;


function Tri(n: integer): array of real;
begin
  var tri := new List<real>;
  tri.Add(3);
  if n = 0 then
    exit(tri.ToArray);
  tri.Add(1);
  if n = 1 then
    exit(tri.ToArray);
  if n = 2 then
  begin
    tri.Add(2);
    exit(tri.ToArray);
  end;
  tri.Add(2);
  tri.Add(1);
  for var i := 3 to n do
  begin
    if i mod 2 = 0 then
      tri.Add(tri[i - 1] + tri[i - 2] + tri[i])
    else
      tri.Add(tri[i - 1] + tri[i - 2] + tri[i] + 1);
  end;
  Result := tri.ToArray;
end;


function Digits(n: integer): integer;
