    if digit mod 2 <> 0 then
    begin
      product := product * digit;
      hasOdd := True;
    end;
  end;
  if hasOdd then
    Result := product
  else
    Result := 0;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in s do
    if ch = '[' then
      stack.Push(ch)
    else if ch = ']' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  Result := stack.Count = 0;
end;


