function Simplify(x, n: string): boolean;
begin
  var (num1, denom1) := (integer.Parse(x.Substring(0, x.IndexOf('/'))), integer.Parse(x.Substring(x.IndexOf('/') + 1)));
  var (num2, denom2) := (integer.Parse(n.Substring(0, n.IndexOf('/'))), integer.Parse(n.Substring(n.IndexOf('/') + 1)));
  var gcd := System.Numerics.BigInteger.GreatestCommonDivisor(denom1, denom2);
  Result := (num1 * denom2 = num2 * denom1) and (denom1 div gcd = denom2 div gcd);
end;


