function EvenOddCount(num: integer): (integer, integer);
begin
  var even := 0;
  var odd := 0;
  var n := Abs(num);
  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 = 0 then
      even += 1
    else
      odd += 1;
    n := n div 10;
  end;
  Result := (even, odd);
end;


function IntToMiniRoman(number: integer): string;
begin
  var roman := new Dictionary<integer, string>;
  roman.Add(1000, 'm');
  roman.Add(900, 'cm');
  roman.Add(500, 'd');
  roman.Add(400, 'cd');
  roman.Add(100, 'c');
  roman.Add(90, 'xc');
  roman.Add(50, 'l');
  roman.Add(40, 'xl');
  roman.Add(10, 'x');
  roman.Add(9, 'ix');
  roman.Add(5, 'v');
  roman.Add(4, 'iv');
  roman.Add(1, 'i');

  var res := '';
  var n := number;

  foreach var kv in roman do
  begin
    while n >= kv.Key do
    begin
      res += kv.Value;
      n -= kv.Key;
    end;
  end;

  Result := res;
end;


function RightAngleTriangle(a, b, c: integer): boolean;
begin
  Result := (a * a + b * b = c * c) or (b * b + c * c = a * a) or (c * c + a * a = b * b);
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var maxWord := '';

  foreach var word in words do
  begin
    var uniqueChars := new HashSet<char>(word.ToLower);
    if uniqueChars.Count > maxUnique then
    begin
      maxUnique := uniqueChars.Count;
      maxWord := word;
    end;
  end;

  Result := maxWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  if remaining >= need then
    Result := (number + need, remaining - need)
  else
    Result := (number + remaining, 0);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 0 to op.Length - 1 do
  begin
    if op[i] = '+' then
      res += operand[i + 1]
    else if op[i] = '-' then
      res -= operand[i + 1]
    else if op[i] = '*' then
      res *= operand[i + 1]
    else if op[i] = '//' then
      res := res div operand[i + 1]
    else if op[i] = '**' then
      res := Round(Power(res, operand[i + 1]));
  end;
  Result := res;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  foreach var c in s do
    if c.IsLetter then
      if c.IsLower then
        sb.Append(c.ToUpper)
      else sb.Append(c.ToLower);
  if sb.Length = 0 then
    sb.Append(s.Reverse.JoinToString(''));
  Result := sb.ToString;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
    Result := nil
  else
    Result := System.Security.Cryptography.MD5.Create().ComputeHash(Encoding.UTF8.GetBytes(text)).ToHexString;
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var evenDigits := new List<integer>;
  for var i := a to b do
    if i mod 2 = 0 then
      evenDigits.Add(i);
  evenDigits.Sort;
  Result := evenDigits.ToArray;
end;
